// # The aliased `len` in a condition is the builtin's pure call, not a call
// # that may run the closure writing the list: the fact the condition proves
// # on that list survives it.
// def aliased_len_cond(xs: list[int32]) -> None:
//     def grow() -> None:
//         xs.append(9)
//     i = 0
//     if i < blen(xs):
//         print("aliased_len_cond", xs[i])  # tpyc: bounds_safe(xs)
//     grow()
//     print("aliased_len_cond grown", xs)
void aliased_len_cond(std::vector<int32_t>& xs) {
    auto grow = [&xs]() {
        xs.push_back(9);
    };
    int32_t i = 0;
    if ((i < ::tpy::__len__(xs))) {
        std::cout << "aliased_len_cond" << " " << xs[static_cast<std::size_t>(i)] << "\n" << ::tpy::check_signals;
    }
    grow();
    std::cout << "aliased_len_cond grown" << " " << ::tpy::ListPrinter(xs) << "\n" << ::tpy::check_signals;
}

